mapper.select:
SELECT p.post_id as postId, p.title, p.content, p.like_count as likeCount, p.dislike_count as dislikeCount, p.report_count as reportCount, p.view_count as viewCount, p.user_id as userId, u.nickname as userNickname, p.category_id as categoryId, c.name as categoryName, p.created_at as createdAt, p.updated_at as updatedAt FROM POST p JOIN USER u ON p.user_id = u.user_id JOIN CATEGORY c ON p.category_id = c.category_id
p.category_id = #{categoryId}
AND ( p.title LIKE CONCAT('%', #{keyword}, '%') OR p.content LIKE CONCAT('%', #{keyword}, '%') )
ORDER BY p.created_at DESC LIMIT #{limit} OFFSET #{offset}

mapper.update:
UPDATE POST
SET view_count = view_count + 1
WHERE post_id = #{postId}

mapper.delete:
DELETE FROM POST
WHERE post_id = #{postId}
  AND user_id = #{userId}
